namespace CheckoutPricing.Domain;

public static class LoyaltyDiscountPolicy
{
    private const int MinimumSubtotalCents = 3000;
    private const int CapCents = 2000;

    public static int Calculate(int subtotalCents, LoyaltyTier tier)
    {
        if (subtotalCents < MinimumSubtotalCents)
        {
            return 0;
        }

        return Math.Min(Cents.Percent(subtotalCents, RatePercent(tier)), CapCents);
    }

    private static int RatePercent(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 10,
        LoyaltyTier.Gold => 15,
        LoyaltyTier.Platinum => 20,
        _ => throw new ArgumentOutOfRangeException(nameof(tier))
    };
}
